    """Type des sessions existantes déduit du nom ; sessions existantes publiées ;
    notes d'examen sans année reprises depuis leur session (elles étaient ignorées des bulletins)."""
    SessionExamen = apps.get_model('school_admin', 'SessionExamen')
    NoteExamen = apps.get_model('school_admin', 'NoteExamen')
    for s in SessionExamen.objects.all():
        nom = (s.nom_examen or '').lower()
        if 'rattrap' in nom:
            s.type_session = 'rattrapage'
        elif 'blanc' in nom:
            s.type_session = 'examen_blanc'
            s.compte_bulletin = False
        elif 'examen' in nom or 'session' in nom:
            s.type_session = 'examen'
        s.est_publie = True
        s.save(update_fields=['type_session', 'compte_bulletin', 'est_publie'])
    for n in NoteExamen.objects.filter(annee_scolaire__isnull=True).select_related('session_examen'):
        if n.session_examen.annee_scolaire_id:
            n.annee_scolaire_id = n.session_examen.annee_scolaire_id
            n.save(update_fields=['annee_scolaire'])


